function extractJson(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;
  const jsonFence = text.match(/\`\`\`(?:json)?\s*([\s\S]*?)\`\`\`/i);
  const candidate = jsonFence ? jsonFence[1].trim() : text;
  try {
    return JSON.parse(candidate);
  } catch (error) {}
  const first = candidate.indexOf('{');
  const last = candidate.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try {
      return JSON.parse(candidate.slice(first, last + 1));
    } catch (error) {}
  }
  return null;
}

function pad(value) {
  return String(value).padStart(2, '0');
}

function cairoIso(date) {
  const fixedCairo = new Date(date.getTime() + 3 * 60 * 60 * 1000);
  return fixedCairo.getUTCFullYear() + '-' + pad(fixedCairo.getUTCMonth() + 1) + '-' + pad(fixedCairo.getUTCDate()) + 'T' + pad(fixedCairo.getUTCHours()) + ':' + pad(fixedCairo.getUTCMinutes()) + ':' + pad(fixedCairo.getUTCSeconds()) + '+03:00';
}

function formatCairo(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value ?? '');
  const iso = cairoIso(date);
  return iso.slice(0, 10) + ' ' + iso.slice(11, 16) + ' \u0628\u062a\u0648\u0642\u064a\u062a \u0627\u0644\u0642\u0627\u0647\u0631\u0629';
}

const parsed = extractJson($json.output);
const originalOutput = String($json.output ?? '').trim();

if (!parsed) {
  return [{
    json: {
      readyToCreate: false,
      replyText: originalOutput || '\u0644\u0645 \u0623\u0633\u062a\u0637\u0639 \u0641\u0647\u0645 \u0627\u0644\u0631\u0633\u0627\u0644\u0629. \u0627\u0643\u062a\u0628 \u0627\u0644\u0645\u0648\u0639\u062f \u0623\u0648 \u0627\u0633\u0645 \u0627\u0644\u062d\u062f\u062b \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.',
    },
  }];
}

if (parsed.action !== 'create_event') {
  return [{
    json: {
      readyToCreate: false,
      replyText: parsed.replyText || parsed.message || '\u0645\u062d\u062a\u0627\u062c \u062a\u0627\u0631\u064a\u062e \u0648\u0648\u0642\u062a \u0648\u0627\u0636\u062d\u064a\u0646 \u0642\u0628\u0644 \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u062d\u062f\u062b.',
    },
  }];
}

const summary = String(parsed.summary || '').trim();
const startDate = new Date(parsed.start);
let endDate = new Date(parsed.end);
const now = new Date();

if (!summary || !parsed.start || Number.isNaN(startDate.getTime())) {
  return [{
    json: {
      readyToCreate: false,
      replyText: '\u0645\u062d\u062a\u0627\u062c \u0639\u0646\u0648\u0627\u0646 \u0648\u0645\u064a\u0639\u0627\u062f \u0648\u0627\u0636\u062d\u064a\u0646 \u0642\u0628\u0644 \u0645\u0627 \u0623\u0636\u064a\u0641 \u0627\u0644\u062d\u062f\u062b \u0644\u0644\u062a\u0642\u0648\u064a\u0645.',
    },
  }];
}

if (startDate <= now) {
  return [{
    json: {
      readyToCreate: false,
      replyText: '\u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0630\u064a \u0648\u062c\u062f\u062a\u0647 \u0642\u062f\u064a\u0645 (' + formatCairo(parsed.start) + ')\u060c \u0644\u0630\u0644\u0643 \u0644\u0645 \u0623\u0636\u0641\u0647 \u0644\u0644\u062a\u0642\u0648\u064a\u0645. \u0627\u0628\u0639\u062a\u0644\u064a \u0627\u0633\u0645 \u0627\u0644\u062d\u062f\u062b \u0645\u0639 \u0643\u0644\u0645\u0629 "\u0627\u0644\u0642\u0627\u062f\u0645" \u0623\u0648 \u062a\u0627\u0631\u064a\u062e \u0645\u062d\u062f\u062f \u0648\u0633\u0623\u0628\u062d\u062b \u0639\u0646\u0647 \u0645\u0646 \u062c\u062f\u064a\u062f.',
      rejectedStart: parsed.start,
      checkedAt: cairoIso(now),
    },
  }];
}

if (!parsed.end || Number.isNaN(endDate.getTime()) || endDate <= startDate) {
  const minutes = Number(parsed.defaultDurationMinutes || 60);
  endDate = new Date(startDate.getTime() + Math.max(minutes, 15) * 60 * 1000);
}

const descriptionParts = [
  parsed.description,
  parsed.source ? 'Source: ' + parsed.source : '',
  parsed.originalRequest ? 'Original request: ' + parsed.originalRequest : '',
].filter(Boolean);

return [{
  json: {
    readyToCreate: true,
    summary,
    start: cairoIso(startDate),
    end: cairoIso(endDate),
    description: descriptionParts.join('\n') || 'Created from Telegram request: ' + summary,
  },
}];

function pad(value) {
  return String(value).padStart(2, '0');
}

function cairoIso(date) {
  const fixedCairo = new Date(date.getTime() + 3 * 60 * 60 * 1000);
  return `${fixedCairo.getUTCFullYear()}-${pad(fixedCairo.getUTCMonth() + 1)}-${pad(fixedCairo.getUTCDate())}T${pad(fixedCairo.getUTCHours())}:${pad(fixedCairo.getUTCMinutes())}:${pad(fixedCairo.getUTCSeconds())}+03:00`;
}

function formatCairo(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value ?? '');
  const iso = cairoIso(date);
  return `${iso.slice(0, 10)} ${iso.slice(11, 16)} بتوقيت القاهرة`;
}

const summary = $json.summary || 'الحدث';
const start = $json.start?.dateTime || $json.start;
const link = $json.htmlLink ? `\nرابط الحدث: ${$json.htmlLink}` : '';

return [{
  json: {
    replyText: `تم إنشاء الحدث في التقويم.\n\n- العنوان: ${summary}\n- الموعد: ${formatCairo(start)}\n- التنبيه: قبل الحدث بـ 60 دقيقة و15 دقيقة${link}`,
  },
}];
